import {Utils} from "./Utils.js";

/**
 * Server-side representation of a remote client.
 *
 * Events emitted:
 * <ul>
 *   <li><code>suspended</code>, when a /meta/connect is suspended by the server</li>
 *   <li><code>resumed</code>, when a /meta/connect is resumed by the server</li>
 *   <li><code>removed</code>, when this ServerSession is removed from the server, either explicitly by
 *   disconnecting or because of a timeout</li>
 * </ul>
 *
 *
 * @param {CometDServer} cometd the CometD server object
 * @param {string} id the session id
 * @returns {ServerSession} a ServerSession object
 * @constructor
 */
export class ServerSession {
    #cometd;
    #id;
    #handshaken = false;
    #extensions = [];
    #listeners = {};
    #subscriptions = [];
    #queue = [];
    #clientTimeout = -1;
    #clientInterval = -1;
    #batch = 0;
    #scheduleTime = 0;
    #expireTime = 0;
    #metaConnectDeliveryOnly = false;
    #flusher = null;

    constructor(cometd, id) {
        this.#cometd = cometd;
        this.#id = id;
    }

    /**
     * @returns {string} the session id
     */
    get id() {
        return this.#id;
    }

    /**
     * @callback sessionIncomingFn
     * @param {ServerSession} session - the session receiving the message
     * @param {object} message - the incoming message
     * @param {boolCallbackFn} callback - the callback to complete:
     * true to continue the processing, false to stop the processing
     */
    /**
     * @callback sessionOutgoingFn
     * @param {ServerSession} [sender] - the session that sends the message
     * @param {ServerSession} session - the session the message is sent to
     * @param {object} message - the outgoing message
     * @param {objectCallbackFn} callback - the callback to complete:
     * a message to continue the processing, null to stop the processing
     */

    /**
     * @typedef {object} SessionExtension
     * @property {sessionIncomingFn} [incoming]
     * @property {sessionOutgoingFn} [outgoing]
     */
    /**
     * Adds the given extension to the list of extensions.
     *
     * @param {SessionExtension} extension the extension to add
     */
    addExtension(extension) {
        this.#extensions.push(extension);
    }

    /**
     * Removes the given extension from the list of extensions.
     *
     * @param {SessionExtension} extension the extension to remove
     * @return {boolean} whether the extension was removed
     */
    removeExtension(extension) {
        let index = this.#extensions.indexOf(extension);
        if (index >= 0) {
            this.#extensions.splice(index, 1);
            return true;
        }
        return false;
    }

    /**
     * @returns {SessionExtension[]} the list of extensions
     */
    get extensions() {
        return this.#extensions.slice();
    }

    /**
     * @param {string} event the event type
     * @returns {function[]} the listeners for the given event
     */
    listeners(event) {
        return this.#listeners[event] || [];
    }

    /**
     * Adds a listener function for the given event.
     *
     * @param {string} event the event type
     * @param {function} fn the listener function
     */
    addListener(event, fn) {
        Utils.addListener(this.#listeners, event, fn);
    }

    /**
     * Removes a listener function for the given event.
     *
     * @param {string} event the event type
     * @param {function} fn the listener function
     */
    removeListener(event, fn) {
        return Utils.removeListener(this.#listeners, event, fn);
    }

    /**
     * Delivers a message to the remote client represented by this ServerSession.
     *
     * @param {ServerSession} [sender] the session that sends the message
     * @param {string} channelName the message channel
     * @param {*} data the message data
     * @param {boolCallbackFn} [callback] the callback notified when the deliver completes
     */
    deliver(sender, channelName, data, callback) {
        const message = {
            channel: channelName,
            data: data
        };
        this.#cometd._log("cometd.session", "delivering", message, "to", this.id);
        this.#deliver(sender, message, callback);
    }

    /**
     * @returns {ServerChannel[]} the channels this session is subscribed to
     */
    get subscriptions() {
        return this.#subscriptions.slice();
    }

    /**
     * Batches the execution of the given function.
     * Messages sent by the execution of the given function are
     * batched and sent only when the function returns.
     *
     * @param {function} fn the batching function
     */
    batch(fn) {
        this._startBatch();
        try {
            fn();
        } finally {
            this._endBatch();
        }
    }

    /**
     * Disconnects this session from the server side.
     *
     * @param {boolCallbackFn} callback the callback notified when the deliver completes
     * @returns {boolean} whether the session has been disconnected
     */
    disconnect(callback) {
        const removed = this.#cometd._removeServerSession(this, false);
        if (removed) {
            this.#deliver(this, {
                successful: true,
                channel: "/meta/disconnect"
            }, callback);
        }
        return removed;
    }


    // PRIVATE APIs.


    get _metaConnectDeliveryOnly() {
        return this.#metaConnectDeliveryOnly;
    }

    set _metaConnectDeliveryOnly(value) {
        this.#metaConnectDeliveryOnly = value;
    }

    get _flusher() {
        return this.#flusher;
    }

    set _flusher(flusher) {
        this.#flusher = flusher;
    }

    #deliver(sender, message, callback) {
        callback = callback || this.#noop;
        this.#cometd._extendOutgoing(sender, this, message, (failure, result) => {
            if (failure) {
                callback(failure);
            } else if (result) {
                this._deliver1(sender, message, callback);
            } else {
                callback(undefined, false);
            }
        });
    }

    _deliver1(sender, message, callback) {
        // TODO: avoid delivering to self ?
        callback = callback || this.#noop;
        this._extendOutgoing(sender, this, message, (failure, result) => {
            if (failure) {
                callback(failure);
            } else if (result) {
                this.#offer(this, Utils.serialize(result));
                if (this.#batch === 0) {
                    this._flush();
                }
                callback(undefined, true);
            } else {
                callback(undefined, false);
            }
        });
    }

    get _hasMessages() {
        return this.#queue.length > 0;
    }

    _handshake() {
        this.#handshaken = true;
    }

    get _handshaken() {
        return this.#handshaken;
    }

    _scheduleExpiration(dftInterval, dftMaxInterval) {
        this.#scheduleTime = Date.now();
        const interval = this.#calculateInterval(dftInterval);
        this.#expireTime = this.#scheduleTime + interval + dftMaxInterval;
    }

    _cancelExpiration(metaConnect) {
        if (metaConnect) {
            this.#expireTime = 0;
        } else if (this.#expireTime !== 0) {
            this.#expireTime += Date.now() - this.#scheduleTime;
        }
    }

    _drainQueue(replies) {
        Utils.notifyEvent(this.listeners("queueDrain"), [this, this.#queue, replies]);
        const queue = this.#queue.slice();
        this.#queue = [];
        return queue;
    }

    _setClientTimeout(timeout) {
        this.#clientTimeout = timeout;
    }

    _calculateTimeout(dftTimeout) {
        if (this.#clientTimeout >= 0) {
            return this.#clientTimeout;
        }
        return dftTimeout;
    }

    _setClientInterval(interval) {
        this.#clientInterval = interval;
    }

    #calculateInterval(dftInterval) {
        if (this.#clientInterval >= 0) {
            return this.#clientInterval;
        }
        return dftInterval;
    }

    _subscribed(channel) {
        this.#subscriptions.push(channel);
    }

    _unsubscribed(channel) {
        for (let i = 0; i < this.#subscriptions.length; ++i) {
            const s = this.#subscriptions[i];
            if (s.name === channel.name) {
                this.#subscriptions.splice(i, 1);
                break;
            }
        }
    }

    _removed(timeout) {
        this.#handshaken = false;
        // Slice the array because _unsubscribe() modifies _subscriptions during the iteration.
        Utils.asyncFoldLeft(this.subscriptions, undefined, (ignored, channel, c) => {
            channel._unsubscribe(this, null, c);
        }, () => {
            Utils.notifyEvent(this.#listeners["removed"], [this, timeout]);
        });
    }

    _flush() {
        if (this.#flusher) {
            this.#flusher.flush();
        }
    }

    _sweep() {
        if (this.#expireTime !== 0) {
            if (Date.now() > this.#expireTime) {
                if (this.#flusher) {
                    this.#flusher.cancel();
                }
                this.#cometd._removeServerSession(this, true);
            }
        }
    }

    _startBatch() {
        ++this.#batch;
    }

    _endBatch() {
        --this.#batch;
        if (this.#batch === 0 && this._hasMessages) {
            this._flush();
        }
    }


    get _isBatching() {
        return this.#batch > 0;
    }

    _extendIncoming(message, callback) {
        Utils.asyncFoldLeft(this.#extensions, true, (result, extension, loop) => {
            if (result) {
                if (extension.incoming) {
                    try {
                        extension.incoming(this, message, (failure, ret) => {
                            loop(failure, ret !== false);
                        });
                    } catch (failure) {
                        this.#cometd._log("cometd.session", "extension failure", failure, failure.stack);
                        loop(undefined, true);
                    }
                } else {
                    loop(undefined, true);
                }
            } else {
                loop(undefined, false);
            }
        }, callback);
    }

    _extendOutgoing(sender, session, message, callback) {
        Utils.asyncFoldLeft(this.extensions.reverse(), message, (result, extension, loop) => {
            if (result) {
                if (extension.outgoing) {
                    try {
                        extension.outgoing(sender, session, result, (failure, msg) => {
                            loop(failure, msg === undefined ? result : msg);
                        });
                    } catch (failure) {
                        this.#cometd._log("cometd.session", "extension failure", failure, failure.stack);
                        loop(undefined, result);
                    }
                } else {
                    loop(undefined, result);
                }
            } else {
                loop(undefined, result);
            }
        }, callback);
    }

    #noop() {
    }

    #offer(session, message) {
        // TODO: queue maxed ?
        this.#queue.push(message);
        Utils.notifyEvent(session.listeners("queueOffer"), [session, message]);
    }
}
